package game

import (
	"crypto/sha256"
	"encoding/base64"
	"fmt"
	"testing"
)

// Exact synthetic envelope produced at 10b1eb94 before Snapshot gained the
// complete SAV document. It is a decode-only fixture, never re-encoded today.
const beforeDocument1115Envelope = ""

func TestDocument1115ReadsPreDocumentEnvelope(t *testing.T) {
	b, err := base64.StdEncoding.DecodeString(beforeDocument1115Envelope)
	if err != nil {
		t.Fatal(err)
	}
	if got := fmt.Sprintf("%x", sha256.Sum256(b)); got != "314905cfa0eb982e2a32d482653babd825ebdc28c6e8e545d8b9dc75ad1e1ca4" {
		t.Fatal("frozen envelope changed", got)
	}
	s, label, err := DecodeSave(b)
	if err != nil {
		t.Fatal(err)
	}
	if label != releasedSaveFixtureLabel || s.Mission != 10 || s.Gold != 321 || s.SavedDocument != nil {
		t.Fatal("old native envelope changed")
	}
}
